from pathlib import Path
import csv,json,subprocess,hashlib,html,re
P=Path(__file__).resolve().parent; R=P.parent.parent
sha='4a9763565f70b9ab1eddde2f5daca07687560948'
md=json.loads((R/'context/21_visual_explainer_draft_20261110/map_data.json').read_text())
rows=list(csv.DictReader((P/'hypothesis_portfolio.csv').open()))
tests={
'C01':('Уфа: согласовать северные и южные рейсы','Сравнить одни и те же рейсы с удобной пересадкой и без неё. Учесть потерю местных продаж при сдвиге и затраты на ожидание/ночёвку.','Расписание и следующее задание самолёта; минимальное время пересадки; спрос и тариф Нижневартовск — Минеральные Воды.','Сколько новых оплаченных поездок нужно, чтобы сдвиг окупился; нужна ли для этого новая база.'),
'C02':('Нижний Новгород: деловая поездка с возвратом','Сравнить поездку Самара — Нижний Новгород — Архангельск на один, два и три рабочих дня с альтернативами.','Даты, часы работы на месте, конкуренты/поезд, доступные самолёты и чистый тариф.','Оправдывает ли удобный календарь дополнительные частоты и расходы.'),
'C03':('Самара: база прямых рейсов','Один недельный набор рейсов в Архангельск, Омск, Нижневартовск и Минводы сравнить с обслуживанием из действующей базы.','Общие даты/самолёты; расходы базы, ТО, ночёвок; спрос каждой пары.','Какой дополнительный доход оправдывает базирование в Самаре.'),
'C04':('Омск: компактная новая база','Сравнить отдельную базу для рейса Омск — Красноярск с продолжением рейса из Екатеринбурга; отдельно сопоставить с новой сетью Насти.','Расписание, наземные операции, экипажи/резерв, потеря результата в Екатеринбурге.','Когда отдельная база выгоднее цепочки. C04 и новая полная сеть Насти — разные составы.'),
'C05':('Красноярск: вход рядом с сильным конкурентом','На поездке Омск — Улан-Удэ или Томск — Иркутск через Красноярск сравнить даты, время и цену с действующим предложением.','Расписания/кресла/тарифы конкурентов; спрос; возможный ответ ценой и частотой.','Какую долю рынка нужно получить и выдерживает ли экономика ответ конкурента.'),
'C06':('Пермь: использовать существующую инфраструктуру или строить базу','Те же направления посчитать с доступной базовой инфраструктурой и с созданием новой.','Документированная роль Перми, действующие мощности/ТО, одинаковый календарь лучей.','Размер разницы затрат и требуемой выручки.'),
'C07':('Екатеринбург — Омск — Красноярск: продлить оборот','Сравнить сохранение рейса Екатеринбург — Омск с его продолжением до Красноярска и возвратом; учесть следующее задание.','Даты и время оборота, спрос Омск — Красноярск, нагрузка/топливо и утраченные продажи.','Покрывает ли новый участок стоимость продолжения и потерю прежней работы.'),
'C08':('Жуковский — Архангельск — Минводы: проверить архивную цепочку','Построить полный оборот для конкретного аналога самолёта и текущих ограничений трассы.','Историческое предложение отдельно от нынешнего; реальные расстояния/обходы, нагрузка, топливо.','Есть ли физически и экономически допустимый современный вариант.'),
'C09':('Самара — Волгоград: треугольный оборот','Сравнить Екатеринбург — Самара — Волгоград — Екатеринбург и обратный порядок с лучшим сохранённым оборотом.','Датированные рейсы; местные и сквозные пассажиры на общих креслах; расходы всех участков.','Выгода всей цепочки, а не только новой связи Самара — Волгоград.'),
'C10':('Сургут: корпоративная смена','На 28 дней построить смены Уфа — Сургут и сравнить 1/2/4 оборота с обычной продажей.','Календарь смен, слабое обратное направление, стоимость рейсов и возможная гарантия заказчика.','Минимальная гарантированная оплата блока кресел; без договора не считаем её выручкой.'),
'C11':('Новый Уренгой: улучшить существующий продукт','Для одной пары сравнить текущее расписание RW, перенос времени тех же рейсов и добавление одной частоты.','Реальная текущая неделя, свои прежние пассажиры, полезные даты возврата.','Какое изменение даёт чистую добавку, а не просто переносит собственные продажи.'),
'C12':('Череповец — Север: партнёрский блок или свои рейсы','На одном рабочем цикле Череповец — Архангельск сравнить покупку блока у партнёра с собственным оборотом.','Предложение перевозчика, календарь, цена блока и полные расходы собственного рейса.','Порог гарантии и более дешёвый способ выполнить поездку.'),
'C13':('Тюмень — Ямал: семейный и сменный спрос','Сравнить прямой рейс Тюмень — Новый Уренгой с сохранением текущих путей RW через другие узлы.','Один общий рынок конечных поездок, календарь смен, конкуренты и собственный переток.','Реальная добавка компании при разделении клиентов по целям поездки.'),
'C14':('Киров — Минводы: санаторный календарь','Для одной пары дат связать самолёт, трансфер и заселение; сравнить собственную программу с продуктом на действующем перевозчике.','Время приёма/заселения, оплаченные дни, номерной фонд, рейсы и договорные права.','Покрывает ли оплаченный пакет все дополнительные расходы, а не только геометрию маршрута.'),
'C15':('Пермь — Минводы: семейный продукт','Возвратный авиапакет сравнить с подвозом в Екатеринбург и существующим рейсом на тех же датах.','Полное время двери–двери, стоимость сопровождения/подвоза, обратный календарь.','За какое удобство пассажир должен доплатить и достаточно ли этого.'),
'C16':('Самара — Минводы: контроль качества спроса','Сверить прогноз с независимой неделей, не участвовавшей в настройке; разобрать направления и сезон.','Независимый счётчик/расписание, единицы сегмент/поездка, период наблюдения.','Можно ли переносить модель на менее изученные рынки вроде Кирова.'),
'C17':('Пермь: зимняя и летняя программы','Посчитать Пермь — Мурманск зимой и Пермь — Горно-Алтайск летом, включая переходы и межсезонье.','Сезонный спрос/тариф, месяцы, перебазирование, резерв и альтернативная работа борта.','Выгоднее ли сезонное переключение одной круглогодичной линии.'),
'C18':('Горно-Алтайск: спортивные группы','Сравнить прямой Екатеринбург — Горно-Алтайск с перелётом в Новосибирск и наземным подвозом.','Даты группы, гарантированная оплата, багаж и ограничения нагрузки, стоимость подвоза.','Порог группы при полной и уменьшенной вместимости.'),
'C19':('Волгоград — Дагестан: короткая поездка','Проверить возврат на 3–4 дня и весь оборот из Жуковского; сравнить прямой рейс, автомобиль и поезд.','Полное время/цена, оба направления, продажи всех участков цепочки.','Достаточно ли ценности короткой поездки для окупаемости полного оборота.'),
'C20':('Томск — Хакасия: группа или регулярная линия','На одних датах сравнить подтверждаемый групповой блок, регулярный рейс и наземный путь.','Размер/оплата группы, расходы рейса, последствия отмены, календарь возврата.','Минимальный платёж и риск отмены; без гарантии — условный продукт.'),
'C21':('Хабаровск: отдельная база','На поездке Улан-Удэ — Хабаровск — Южно-Сахалинск проверить отличие от существующих перевозчиков.','Даты/частоты/цены, удалённое ТО и резерв, стоимость базы.','Хватает ли платного преимущества для новой удалённой инфраструктуры.'),
'C22':('Сибирь — Забайкалье: цепочка и текущий маршрут','Отдельно оценить треугольник через Иркутск и улучшение Барнаул — Чита; не сложить одних клиентов дважды.','Точный аэропортовый ключ, реальные действующие рейсы, конкуренты, общие рынки.','Какая конкретная программа даёт добавочный результат.'),
'C23':('Якутск — Нерюнгри — Благовещенск: тонкий узел','Проверить тип/нагрузку и полный оборот; отдельно коммерческую и поддерживаемую программу.','Ограничения аэропортов/самолёта, спрос, весь календарь, подтверждаемая поддержка.','Порог гарантированной оплаты и физически допустимая вместимость.'),
'C24':('Сахалин — Камчатка: защищённая поездка через партнёра','На двух реальных рейсах собрать одну поездку через Хабаровск и сравнить с самостоятельной программой.','Рейсы/остатки мест, время пересадки, ответственность за сбой, расчёты между партнёрами.','Окупается ли партнёрский продукт без собственной новой базы.'),
'C25':('Калининград — Поволжье: длинный оборот','Посчитать полный Жуковский — Калининград — Нижний Новгород — Жуковский с разрешённой трассой.','Обходы/время/топливо, нагрузка, день возврата, существующие альтернативы.','Окупается ли цепочка после учёта ограничений и всех участков.'),
'C26':('Коми — Архангельск — Мурманск: северные связи','Сравнить полный оборот с меньшим типом на тех же датах и с одинаковым резервом восстановления.','Платные места/поддержка, доступный тип, календарь и затраты.','Порог спроса и подходящая вместимость, а не автоматический выбор SSJ.'),
'C27':('Челябинск → Екатеринбург: наземный подвоз','Для конкретного дальнего рейса построить автобус туда/обратно и проверить остаток мест самолёта.','Расписание автобуса/рейса, единая зона спроса, остаточная ёмкость, цена подвоза.','Когда подвоз выгоднее новой авиалинии или базы.'),
'C28':('Нижний Новгород, Чебоксары, Саранск: зона доступа','Для одной территории сравнить доступ к одному дальнему продукту через три аэропорта.','Дорожное время, расписание, тариф, жители одной территории без тройного учёта.','В каком аэропорту обслуживать один и тот же спрос.'),
'C29':('Саратов, Волгоград, Астрахань: наземная альтернатива','Авиационный подвоз сравнить с наземным доступом, включая обратную поездку и стыковку.','Полное время, цена, остатки мест и потребность в дополнительном рейсе.','Когда короткий авиаперелёт оправдан относительно дороги.'),
'C30':('Доступность южных аэропортов: условная ветвь','Посчитать текущую доступность и отдельную ветвь после разрешения работы аэропорта.','Официальный статус, готовность, потеря части вынужденного потока Сочи/Минвод.','Что меняем после события; дату и вероятность открытия не выдумываем.'),
'C31':('Замена типа: освободить SSJ','Сравнить сохранение SSJ на Екатеринбург — Минводы с доступной заменой и применением SSJ на Екатеринбург — Омск.','Доступность обоих типов, ёмкость/частота, ТО/экипажи и продажи обеих программ.','Выгода двух изменений вместе; замена не создаёт бесплатный самолёт.'),
'C32':('Событийная группа вместо круглогодичного рейса','Для одного события посчитать 1–2 оборота и сравнить с обычным рейсом или поездом.','Даты/город группы, гарантированный платёж, отмена и альтернативная работа борта.','Порог договора и отсутствие обязательств летать весь год.'),
'C33':('Переставить существующую сеть RW','На одной реальной неделе Екатеринбург — Нижний Новгород/Омск/Минводы сохранить рейсы и поменять время.','Текущие борта/рейсы/стыковки, новые и утраченные связи, местные продажи.','Есть ли рост без новых самолётов после всех потерь.'),
'C34':('Резерв и восстановление сети','Для одного заданного сбоя сравнить место резерва, перегон, перенос и отмену.','Исправный резерв, экипаж, время перегона, места на альтернативных рейсах, деньги.','Сколько поездок сохраняем и какой резерв оправдан; частоту сбоя не выдумываем.'),
'C35':('Ижевск — Екатеринбург — Омск: партнёрская пересадка','Сравнить единый защищённый продукт с самостоятельной пересадкой и наземным путём.','Рейсы обоих операторов, остатки кресел, договор разделения выручки и ответственности.','Условие выгодного партнёрства; один тариф не начислять каждому перевозчику целиком.')}
assert set(tests)=={r['id'] for r in rows}
ideas=[]
for r in rows:
 title,test,data,decision=tests[r['id']]
 ideas.append(dict(id=r['id'],title=title,test=test,data=data,decision=decision,family=r['family_label'],historical_state=r['historical_scope']))
(P/'concrete_experiments.json').write_text(json.dumps({'purpose':'proposed checks, not completed research','version':sha,'ideas':ideas},ensure_ascii=False,indent=2)+'\n')
# Extract the existing geographic renderer; retain geographic data and labels, replace only its page-specific controls.
renderer=(R/'context/21_visual_explainer_draft_20261110/maps.js').read_text().split('function setSelection(id)')[0]
for m in md['maps'].values(): m.pop('explanation',None)
md['maps']={k:v for k,v in md['maps'].items() if k in tests}
