econdary,#edf3f6);stroke:none}.map-grid{fill:none;stroke:var(--border,#d9dfe3);stroke-dasharray:3 4}.map-axis,.map-code{font-size:12px;fill:var(--muted-foreground,#57636f)}.map-route{fill:none;stroke:var(--primary,#bd3348);stroke-width:3;stroke-dasharray:7 4}.map-point{fill:var(--primary,#bd3348)}.map-base{fill:none;stroke:var(--primary,#bd3348);stroke-width:2}.map-label{font-size:17px;font-weight:600;fill:var(--foreground,#20272e);paint-order:stroke;stroke:var(--card,#fff);stroke-width:4px;stroke-linejoin:round}.map-leader{stroke:var(--muted-foreground,#78848a);stroke-width:.7}.idea-controls{display:flex;gap:12px;flex-wrap:wrap;margin:15px 0}select{font:inherit;min-width:0;width:100%;padding:10px;color:var(--foreground,#222);background:var(--card,#fff);border:1px solid var(--border,#ccd4dc);border-radius:6px}.stage{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.stage .box{padding:11px}.stage strong{display:block;margin-bottom:8px}.mobile-toc{display:none}dl{margin:15px 0}dt{font-weight:650;margin-top:12px}dd{margin:4px 0 12px}.chip{font-size:13px;color:var(--muted-foreground,#626b76)}ul,ol{padding-left:22px}.source{font-size:12px;overflow-wrap:anywhere}button{font:inherit;padding:8px;border:1px solid var(--border,#ddd);background:var(--card,#fff);color:var(--foreground,#222);border-radius:6px}@media(max-width:950px){.layout{display:block}.toc{display:none}.mobile-toc{display:block;position:sticky;top:0;background:var(--background,#fff);z-index:3}.mobile-toc summary{padding:8px}.mobile-toc a{display:block;padding:6px}.flow{grid-template-columns:1fr}.stage{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.cards,.compare{grid-template-columns:1fr}h1{font-size:24px}th,td{padding:8px 5px}.box{padding:12px}}</style>'''
links='<a href="#sources">Данные</a><a href="#fixes">Омск и поддержка</a><a href="#demand">Спрос</a><a href="#fleet">Самолёты</a><a href="#network">Сеть</a><a href="#ideas">Все 35 идей</a><a href="#services">Сервисы и №2</a><a href="#outcome">Результат</a>'
body='''<h1>Конкретные проверки Red Wings</h1><p>Проверяем, какую сеть выгодно и возможно запустить, при каком ресурсе и что делать, если условия изменятся. Ниже — задания на расчёт. Из новых результатов уже есть ограниченная проверка модели Насти; остальная программа ещё не выполнена.</p>
<section id="sources"><h2>1. Какие данные соединяем</h2><div class="flow"><div class="box"><span class="label">НАБЛЮДЕНИЯ</span><h3>Рейсы, рынок, самолёты</h3><p>Кто летает, когда, сколько рейсов и кресел; потоки аэропортов; цены; ограничения и поставки.</p></div><div class="box"><span class="label">ОЦЕНКИ</span><h3>Поездки и доступный ресурс</h3><p>Убираем чужие пересадки из потока, оцениваем сезонный спрос и чистый тариф. Отделяем весь парк от рабочего ресурса проекта.</p></div><div class="box"><span class="label">РЕШЕНИЕ</span><h3>Рейсы и деньги</h3><p>Составляем календарь, продаём общий спрос в пределах кресел, считаем изменения всей затронутой сети.</p></div></div>
<div class="matrix"><table><thead><tr><th>Что уже собрано</th><th>Настоящий пример</th><th>Что проверяем / добираем</th></tr></thead><tbody>
<tr><td>Нынешние рейсы RW<br><small>41 пара в rw_routes_now</small></td><td>Самара — Екатеринбург: 7 рейсов в неделю в каждую сторону, публикация на 7–13 декабря 2026.</td><td>Выполняемый тип и кресла, другие сезоны, борта/ротации. Это опубликованное расписание, не доказательство свободного самолёта.</td></tr>
<tr><td>Спрос по парам<br><small>1 428 строк demand_estimates</small></td><td>Омск — Новосибирск: 106 309 наблюдённых сегментов; модельная доля конечных поездок 17,4%; оценка 18 498 поездок.</td><td>Источник сегментов, смысл доли и сезон; независимые пары для проверки. Сегменты и конечные поездки не складываем.</td></tr>
<tr><td>Предложенная сеть<br><small>network_routes</small></td><td>Омск — Иркутск: в base_sub предложено 9 рейсов в неделю в каждую сторону, около 74 755 сегментов в год.</td><td>Оценки спроса в самой таблице расходятся в 9,8 раза. Проверить их, затем пересчитать частоту и деньги.</td></tr>
<tr><td>Парк и расходы<br><small>network.csv, fleet_ramp, проверки Цири</small></td><td>Ступени Насти: 3/4/6/8 самолётов с авторским резервом. Есть расходы SSJ и проверки модификаций.</td><td>Календарь ввода, ТО и резерв; пригодность аналога SJ100/ПД-8; прежние задания действующих бортов.</td></tr>
<tr><td>Поддержка и конкуренты</td><td>В модели 1 773 ₽ на учитываемый немосковский сегмент; четыре разбора региональных баз.</td><td>Право конкретного маршрута на субсидию и её лимит. По финалистам — реальные частоты/цены конкурентов, а не только описание их хабов.</td></tr></tbody></table></div>
<p class="source">Примеры — версия Насти 4a976356 от 17:04, автор kiruha355. Наблюдение, авторская оценка и предложение подписаны раздельно.</p></section>
<section id="fixes"><h2>2. Два отдельных вопроса к выбору Омска</h2>
<div class="experiment"><h3>Проверка 1. Не пропускает ли алгоритм лучший допустимый вариант?</h3><div class="compare"><div class="box"><span class="label">ЛИМИТ 10</span><p>Алгоритм выбрал 5 самолётов и 8 лучей.</p><p class="num"><b>−367,06 млн ₽/год</b></p></div><div class="box"><span class="label">ЛИМИТ 4</span><p>Найдено 4 самолёта и 8 лучей. Эта сеть также помещается в лимит 10.</p><p class="num"><b>−186,48 млн ₽/год</b></p></div></div>
<div class="bars" aria-label="Размер отрицательного результата, млн рублей"><div><div class="barlabel">Выбор при лимите 10 · убыток 367,06</div><div class="bar" style="width:100%"></div></div><div><div class="barlabel">Допустимая альтернатива · убыток 186,48</div><div class="bar" style="width:50.8%;opacity:.6"></div></div></div>
<p>Оба числа — модельный результат до аренды и базы, не полная прибыль. Контрпример воспроизведён отдельным проверяющим.</p><p class="result"><b>Работа:</b> сохранять и сравнивать все уже найденные допустимые сети; проверить остальные хабы и прямые при тех же ограничениях. <b>Решение:</b> изменится ли победитель после устранения известного пропуска. Положительную прибыль этим примером не доказали.</p></div>
<div class="experiment"><h3>Проверка 2. При какой поддержке Омск становится приемлемым?</h3><div class="flow"><div class="box"><h3>Фиксированная сеть</h3><p>12 лучей, 8 самолётов. Без поддержки: около <b>−706,41 млн ₽/год</b>.</p></div><div class="box"><h3>Сценарная поддержка</h3><p>Около <b>1 094,13 млн ₽/год</b> в авторской модели.</p></div><div class="box"><h3>Остаток до прочих затрат</h3><p>Около <b>+387,72 млн ₽/год</b>. Из него ещё покрываются неучтённые расходы.</p></div></div>
<p><b>Уже найденная граница:</b> примерно 1 144,71 ₽ на учитываемый сегмент покрывают только этот модельный дефицит при прежних продажах. Это не подтверждённая ставка и не порог полной прибыли.</p><p class="result"><b>Данные:</b> первичные условия программы, допустимые маршруты, получатель, единица оплаты и предел. <b>Опыт:</b> та же сеть без/с поддержкой, затем новый выбор сети при каждом условии. <b>Решение:</b> можно ли рекомендовать Омск; какая поддержка и какой предел прочих затрат нужны.</p></div></section>
<section id="demand"><h2>3. Проверяем, кому и сколько продаём</h2>
<div class="flow"><div class="box"><h3>Пассажиры на рейсе</h3><p>Омск — Новосибирск: <b>106 309 сегментов</b>.</p></div><div class="box"><h3>Часть едет дальше</h3><p>Авторская модель оставляет <b>17,4%</b> как поездки между этими городами.</p></div><div class="box"><h3>Рынок конечной пары</h3><p><b>18 498 поездок</b> после округления. Долю необходимо проверить.</p></div></div>
<p class="question">Проверка 3: не принимает ли модель поток через аэропорт за спрос на наш новый рейс и не делает ли короткий сезон годовым потоком?</p>
<div class="compare"><div class="box"><h3>Что делаем</h3><p>Берём известные пары, отделяем часть для независимой проверки, сравниваем оценку с наблюдениями. Для Омск — Иркутск разбираем причины расхождения оценок. Меняем сезон, частоту и захват конкурирующих предложений по отдельности.</p></div><div class="box"><h3>Что получаем</h3><p>Интервал спроса/тарифа по каждой финальной паре; объяснение частоты; какие маршруты исчезают при осторожных входах. Если данных для прогноза нет — требуемые платные места и тариф, с проверкой их правдоподобия.</p></div></div>
<p class="small">Продолжительность сезона меняет число выполненных рейсов и доступный спрос. Нельзя автоматически уместить тот же годовой спрос в 48 недель вместо 52. Ценовой ползунок при постоянном спросе — только арифметическая чувствительность.</p></section>
<section id="fleet"><h2>4. Самолёты: когда появляется возможность летать</h2>
<div class="stage"><div class="box"><strong>Поставлен</strong><small>Получен конкретный тип самолёта</small></div><div class="box"><strong>Введён</strong><small>Готовы экипаж, ТО, документы</small></div><div class="box"><strong>Выделен</strong><small>Известны резерв и другие задания</small></div><div class="box"><strong>Работает</strong><small>Проверена полная цепочка рейсов</small></div></div>
<p class="question">Проверка 4: какой этап сети выполняется по месяцам при полной, частичной и поздней поставке — и что остаётся при нуле новых самолётов?</p>
<div class="matrix"><table><thead><tr><th>Ветвь</th><th>Что пересчитываем</th><th>Какое решение нужно</th></tr></thead><tbody>
<tr><td>Партии приходят по этапам</td><td>Месяц ввода каждого борта; запуск маршрутов; доход/расход только реально выполняемых месяцев.</td><td>Какая минимальная партия запускает пилот и когда расширять сеть.</td></tr>
<tr><td>Пришла только часть</td><td>Лучший сокращённый набор при том же спросе; обязательства базы, резерв, экипажи.</td><td>Что сохраняем и что переносим; не распределяем половину борта по всем маршрутам.</td></tr>
<tr><td>Партии задержаны</td><td>Сдвиг на 3/6/12 месяцев как стресс, сезон, уже понесённые расходы, временная программа.</td><td>Когда ждать, когда запускать меньший вариант, когда отказаться от обязательств.</td></tr>
<tr><td>Новых бортов нет</td><td>Текущий парк: расписание, частоты, сезонность, замена типа; прежние задания и потери.</td><td>Какие действия дают чистый рост без нового парка; что не обещать.</td></tr></tbody></table></div>
<p class="small">Числа 3/4/6/8 — контрольные размеры программы Насти, не график поставок. Вторая половина 2027 — ограничение кейса. Даты партий и задержки в опыте не объявляются прогнозом.</p></section>
<section id="network"><h2>5. Какие сетевые решения сравниваем</h2><div class="cards"><div class="box"><h3>А. Улучшить действующую сеть</h3><p>Перестановка рейсов из Екатеринбурга; зимняя/летняя работа из Перми; замена типа; общий резерв. Новые борта не предполагаются бесплатно.</p><p class="chip">C07, C11, C17, C31, C33, C34 и связанные варианты</p></div><div class="box"><h3>Б. Прямые рейсы из существующих баз</h3><p>Добавлять конкретные пары и полный оборот самолёта. Считать все участки треугольника и альтернативную работу борта.</p><p class="chip">Авторская прямая сеть + C08, C09, C22 и подходящие продукты</p></div><div class="box"><h3>В. Новый или расширенный хаб</h3><p>Омск проверяем первым как новый выбор Насти. Сохраняем сравнение с её Самарой, Оренбургом, Уфой и Нижним Новгородом. База должна окупать свои дополнительные расходы.</p><p class="chip">C01–C06; дальневосточные C21/C23 проходят первичный разбор</p></div><div class="box"><h3>Г. Смешанная программа</h3><p>Добавляем только полезные элементы А–В при одном парке и одном спросе. Нельзя сложить независимые прибыли и заново продать те же места.</p><p class="chip">Не новый произвольный балл; совместный календарь и бюджет</p></div></div>
<p class="result"><b>Проверка 5:</b> сравнить эти действия с сохранением сети в том же 2027/2028 году. На карте результата: сохранённые, добавленные, сокращённые и сдвинутые рейсы; рядом самолёт, частота, конкуренты и добавочный результат. История 2025 служит контекстом, а не автоматически будущей базой сравнения.</p></section>
<section id="ideas"><h2>6. Конкретный следующий опыт для каждой из 35 идей</h2><p>Все карточки сохраняются. Корпоративные/сезонные продукты и подвоз проверяем как возможные улучшения финальной сети. Удалённая база и длинные тонкие маршруты сначала должны выдержать проверку самолёта, конкуренции и минимального платного спроса.</p>
<label for="idea-select"><b>Гипотеза и её проверка</b></label><div class="idea-controls"><select id="idea-select"></select></div><div id="idea-text"></div><div class="map-canvas" id="idea-map"></div><p class="small muted">География исходной гипотезы, не действующее расписание. Линии не задают траекторию полёта. Для решения добавляем текущие рейсы, календарь и бюджет; Москва без выбранного аэропорта не получает выдуманную точку.</p><div id="idea-routes" class="small"></div>
<div class="flow"><div class="box"><h3>Есть основание проверить</h3><p>Действие, пассажир, конкретные данные и сравнение.</p></div><div class="box"><h3>Есть объяснимый исход</h3><p>Оценена; доказан отказ; включена в проверенную общую программу; условна по точному параметру.</p></div><div class="box"><h3>Либо работа не выполнена</h3><p>Это незавершённость. Отсутствие времени или отдельного теста не доказывает невыгодность.</p></div></div></section>
<section id="services"><h2>7. Дополнительные вопросы: законченные отдельные материалы</h2><div class="matrix"><table><thead><tr><th>Гипотеза</th><th>Конкретная проверка</th><th>Результат</th></tr></thead><tbody>
<tr><td>Меньше препятствий при покупке</td><td>Одна реальная покупательская задача до оплаты: поиск, выбор тарифа/багажа, исправление ошибки. Выявить препятствие; сравнить нынешний и предложенный путь.</td><td>Скрин/макет; затраты; какой прирост завершённых покупок окупает изменение. Ограничение свободными креслами.</td></tr>
<tr><td>Больше чистого дохода от допуслуг</td><td>Проверить уже продаваемые услуги и момент предложения. Учесть себестоимость, замену старой услуги и возможный отказ от покупки.</td><td>Порог дополнительных покупок услуги, предложение теста; не выдуманный процент роста.</td></tr>
<tr><td>Проще решить вопрос после покупки</td><td>Изменение/возврат/обращение при сбое. Отдельно отметить шаги, недоступные без настоящего билета.</td><td>Конкретная автоматизация, порог экономии обращений, ответственность и цена внедрения.</td></tr>
<tr><td>Первый этап приближает к №2</td><td>Проверить годовой рейтинг отдельных перевозчиков и масштаб разрыва; прибавить только чистый эффект выбранной программы при общем флоте.</td><td>Какую часть задачи закрываем к2028 и какой ресурс нужен дальше. Срок достижения №2 не задан.</td></tr></tbody></table></div><p class="small">Это содержание исследования и приложения к паспорту. Работа с интерфейсом дашборда Насти в эту программу не входит. Наличие у RW сервиса не считается отсутствием; сначала проверяем реальную проблему.</p></section>
<section id="outcome"><h2>8. Что должно оказаться перед командой</h2><div class="flow"><div class="box"><h3>Сеть и ресурс</h3><p>Карта было/стало, 8–12 финальных пар, частоты/типы, расписание, поставки и резерв по этапам.</p></div><div class="box"><h3>Сравнение и развилки</h3><p>Пассажиры/выручка/доля, полный добавочный результат, денежная потребность и условия смены выбора.</p></div><div class="box"><h3>Решение для паспорта</h3><p>Что рекомендуем при каких условиях, что запускаем первым, от чего отказываемся и почему. Иллюстрации допвопросов отдельно.</p></div></div>
<p>Первыми идут исправление известного выбора, поддержка и спрос. Без них новые сценарии только размножат недостоверный вывод. Работа по парку, исходной сети и дополнительным продуктам может идти параллельно.</p><p class="source">Входы: Настя 4a976356; аудит 35 идей 9b65c9ff; географический пакет context21; новый ограниченный replay дашборда 0cf4a64f. Новые экономические опыты этой программы ещё не выполнены.</p></section>'''
js='''const IDEAS=JSON.parse(document.getElementById('idea-data').textContent);const select=document.getElementById('idea-select');
for(const it of IDEAS){const o=document.createElement('option');o.value=it.id;o.textContent=it.id+' · '+it.title;select.append(o)}
function showIdea(id){const i=IDEAS.find(v=>v.id===id),m=DATA.maps[id];document.getElementById('idea-text').innerHTML='<dl><dt>Что сравниваем</dt><dd>'+xml(i.test)+'</dd><dt>Какие данные нужны</dt><dd>'+xml(i.data)+'</dd><dt>Какое решение получаем</dt><dd>'+xml(i.decision)+'</dd></dl>';
const missing=[...new Set(m.paths.flat().filter(c=>!DATA.airports[c]))];const original=m.paths;const originalMissing=m.missing;const originalEdges=m.edges;
const known=originalEdges.filter(e=>e.every(c=>DATA.airports[c]));const nodes=[...new Set(original.flat().filter(c=>DATA.airports[c]))];m.paths=[...known,...nodes.map(c=>[c])];m.edges=known;m.missing=[];
document.getElementById('idea-map').innerHTML=nodes.length?renderMap(id):'<p>Нет определённых аэропортов для карты.</p>';m.paths=original;m.missing=originalMissing;m.edges=originalEdges;
const name=c=>c==='MOW'?'Москва (аэропорт не выбран)':cityName(c);
document.getElementById('idea-routes').innerHTML='<ul>'+original.map(p=>'<li>'+p.map(c=>xml(name(c))).join(' → ')+'</li>').join('')+'</ul>'+(missing.length?'<p>Неопределённые аэропорты: '+missing.map(c=>xml(name(c))).join(', ')+'.</p>':'');select.value=id;}
select.addEventListener('change',e=>showIdea(e.target.value));showIdea('C04');window.experimentMap={showIdea,ideas:IDEAS};document.querySelectorAll('.mobile-toc a').forEach(a=>a.addEventListener('click',()=>a.closest('details').open=false));'''
page='<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Red Wings — конкретные проверки</title>'+style+'<body><details class="mobile-toc"><summary>Разделы</summary>'+links+'</details><div class="layout"><nav class="toc" aria-label="Разделы">'+links+'</nav><main>'+body+'</main></div><script id="map-data" type="application/json">'+json.dumps(md,ensure_ascii=False).replace('</','<\\/')+'</script><script id="idea-data" type="application/json">'+json.dumps(ideas,ensure_ascii=False).replace('</','<\\/')+'</script><script>'+renderer+'\n'+js+'</script></body></html>'
(P/'work-experiments.html').write_text(page)
# Exact examples used in the document, without rerunning author outputs.
files=['data/manual/rw_routes_now.csv','data/processed/demand_estimates.csv','data/processed/network_routes.csv']
manifest=[]
for f in files:
 b=subprocess.check_output(['git','show',sha+':'+f]);manifest.append({'commit':sha,'path':f,'sha256':hashlib.sha256(b).hexdigest()})
(P/'concrete_sources.json').write_text(json.dumps({'model_examples':manifest,'limited_replay_commit':'0cf4a64f3db8c21f5d929de0f1f0942503b45adb','limited_replay_report':'context/26_strategy_reset_20261110/nastya_panel_review/report.md','interpretation':'author scenario and independent bounded replay; not market acceptance','maps_path':'context/21_visual_explainer_draft_20261110/map_data.json','maps_sha256':hashlib.sha256((R/'context/21_visual_explainer_draft_20261110/map_data.json').read_bytes()).hexdigest(),'ideas':35},ensure_ascii=False,indent=2)+'\n')
print('Built',len(ideas),'specific experiments;',len(page),'HTML chars')
